import { spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { readFile, realpath, stat } from "node:fs/promises";
import { basename, resolve } from "node:path";
import { fileURLToPath } from "node:url";

// Self-contained so the existing isolated runner can stage this probe without
// shared dependency changes. This is the exact standalone spec, not expected
// runtime output. Update the source/hash together when the reviewed spec changes.
export const SPEC_SHA256 = "6f068df7a79a9783396ab79b86ba5cac08c97dad13296a3730e8da7fbe09f788";
export const EMBEDDED_SPEC_BASE64 = "";
export const RACE_CASES = Object.freeze([
  ["b_save_one", "verify_one"], ["b_save_replay", "verify_replay"],
  ["b_save_after_status", "verify_status"], ["b_save_after_cancel", "verify_cancel"],
  ["b_save_after_archive", "verify_archive"], ["b_save_cross_track", "verify_cross_track"],
  ["b_save_after_director", "verify_director_fk"],
]);
const hash = value => createHash("sha256").update(value).digest("hex");
const fail = code => { throw new Error(code); };

export function embeddedSpec() {
  const bytes = Buffer.from(EMBEDDED_SPEC_BASE64, "base64");
  if (hash(bytes) !== SPEC_SHA256) fail("registration_guard_race_spec_hash_mismatch");
  return bytes.toString("utf8");
}

export function buildRacePlan() {
  const spec = embeddedSpec();
  return { status: "plan", sqlExecuted: false, specSha256: SPEC_SHA256, permutations: RACE_CASES.length,
    sessions: [...spec.matchAll(/^session /gm)].length,
    executionContext: "owned disposable loopback database from run-isolated-supabase-db-tests.mjs",
    requiredBinary: "isolationtester (PostgreSQL) 17.x on the runner PATH",
    runtimeGate: "seven completed verification steps, seven observed lock waits, seven committed cleanup checkpoints, no SQL or teardown errors" };
}

export function validateIsolatedContext({ environment, cwd, config }) {
  if (!/^[a-f0-9]{32}$/.test(environment.TASK_LOCAL_DB_NONCE || "")) fail("registration_guard_race_nonce_invalid");
  if (!/^tips-supabase-db-qa-[a-z0-9][a-z0-9-]{7,127}$/.test(basename(cwd))) fail("registration_guard_race_owned_cwd_required");
  let url;
  try { url = new URL(environment.TASK_LOCAL_DB_URL); } catch { fail("registration_guard_race_local_url_invalid"); }
  if (!["postgres:", "postgresql:"].includes(url.protocol) || url.hostname !== "127.0.0.1"
    || url.username !== "postgres" || url.pathname !== "/postgres" || url.search || url.hash
    || !/^\d+$/.test(url.port) || Number(url.port) < 1024 || Number(url.port) > 65535) {
    fail("registration_guard_race_loopback_required");
  }
  const project = config.match(/^project_id\s*=\s*"(tips_supabase_db_qa_[a-f0-9]{12})"\s*$/m)?.[1];
  const databaseSection = config.match(/^\[db\]\s*$([\s\S]*?)(?=^\[|$(?![\s\S]))/m)?.[1] || "";
  const port = databaseSection.match(/^port\s*=\s*(\d+)\s*$/m)?.[1];
  const major = databaseSection.match(/^major_version\s*=\s*(\d+)\s*$/m)?.[1];
  if (!project || Number(port) !== Number(url.port) || major !== "17") fail("registration_guard_race_owned_config_required");
  return { projectId: project, port: Number(port), databaseMajorVersion: 17 };
}

// PostgreSQL isolationtester can return zero after a step emits ERROR or a
// teardown fails. Its exit code alone is never sufficient runtime evidence.
// PG17 PQprint uses aligned single-column tables for this fixed spec. Consume
// complete tables; a valid SQL/result prefix cannot excuse extra output.
function singleColumnResult(column, value = "") {
  const width = Math.max(column.length, value.length);
  return `${column.padEnd(width)}\n${"-".repeat(width)}\n${value.padEnd(width)}\n(1 row)\n\n`;
}

function expectedStepResult(name, sql) {
  if (name === "a_commit" || name === "b_commit") return "";
  if (name === "a_begin" || name === "b_begin") return singleColumnResult("actor");
  const lockedIds = { a_cancel_fixture: [204, 304], a_archive_fixture: [205], a_hold_director_track: [308] }[name];
  if (lockedIds) return lockedIds.map(id => singleColumnResult("id", `a9710000-0000-4000-8000-${String(id).padStart(12, "0")}`)).join("");
  if (/^SELECT registration_guard_race_fixture\.capture\(/.test(sql)) return singleColumnResult("capture");
  fail("registration_guard_race_step_result_contract_missing");
}

export function validateIsolationOutput({ code, stdout, stderr }) {
  if (code !== 0 || typeof stdout !== "string" || typeof stderr !== "string") fail("registration_guard_race_process_failed");
  if (/(?:^|\n)\s*(?:ERROR|FATAL|PANIC):|timed out|canceling step|failed:|failed to|unexpected result|mutually-blocking/i.test(`${stdout}\n${stderr}`)) {
    fail("registration_guard_race_runtime_error");
  }
  const sessionCount = [...embeddedSpec().matchAll(/^session /gm)].length;
  if (!new RegExp(`^Parsed test spec with ${sessionCount} sessions\\s*$`, "m").test(stdout)) fail("registration_guard_race_session_count_invalid");
  const sections = stdout.split(/^starting permutation:/m).slice(1);
  if (sections.length !== RACE_CASES.length) fail("registration_guard_race_permutation_count_invalid");
  const specPermutations = [...embeddedSpec().matchAll(/^permutation\s+(.+)$/gm)]
    .map(match => [...match[1].matchAll(/"([^"]+)"/g)].map(step => step[1]).join(" "));
  const stepSql = new Map([...embeddedSpec().matchAll(/^step "([^"]+)"\s*\{([^}]*)\}/gm)]
    .map(match => [match[1], match[2].trim()]));
  const cleanupResults = [];
  for (const [index, section] of sections.entries()) {
    const [waitStep, verifyStep] = RACE_CASES[index];
    if (section.split("\n", 1)[0].trim() !== specPermutations[index]) fail("registration_guard_race_permutation_order_invalid");
    // SQL is printed verbatim, including embedded newlines. Bound each record
    // by the next step header, then match the expected SQL and wait suffix.
    // A wildcard must never borrow a marker from another step or permutation.
    const headers = [...section.matchAll(/^step ([^:\n]+): /gm)];
    const records = headers.map((header, position) => ({
      name: header[1],
      body: section.slice(header.index + header[0].length, headers[position + 1]?.index ?? section.length),
    }));
    const waits = records.filter(record => record.name === waitStep);
    const waitSuffix = " <waiting ...>";
    if ((section.match(/<waiting \.\.\.>/g) || []).length !== 1
      || (section.match(/<\.\.\. completed>/g) || []).length !== 1
      || waits.length !== 2 || !waits[0].body.trimEnd().endsWith(waitSuffix)
      || waits[0].body.trimEnd().slice(0, -waitSuffix.length).trim() !== stepSql.get(waitStep)
      || !/^<\.\.\. completed>\ncapture[ \t]*\n-+\n[ \t]*\n\(1 row\)\n[ \t\n]*$/.test(waits[1].body)) {
      fail("registration_guard_race_lock_wait_missing");
    }
    const launched = records.filter(record => record !== waits[1]);
    if (launched.map(record => record.name).join(" ") !== specPermutations[index]
      || records.indexOf(waits[1]) <= records.findIndex(record => record.name === "a_commit")
      || records.indexOf(waits[1]) >= records.findIndex(record => record.name === "b_commit")) {
      fail("registration_guard_race_step_order_invalid");
    }
    for (const record of launched) {
      if (record === waits[0]) continue;
      const sql = stepSql.get(record.name);
      const body = record.body.trimStart();
      if (!body.startsWith(`${sql}\n`)) {
        fail("registration_guard_race_step_sql_invalid");
      }
      if (record.name !== verifyStep && body.slice(sql.length).trim() !== expectedStepResult(record.name, sql).trim()) {
        fail("registration_guard_race_step_result_invalid");
      }
    }
    const verification = launched.find(record => record.name === verifyStep);
    const result = verification.body.trimStart().slice(stepSql.get(verifyStep).length);
    // Exactly one assertion table, then each session's own teardown result.
    // Only the observed ROLLBACK warning is optional, in its known position.
    const assertionTable = singleColumnResult("assert_case");
    if (!result.trimStart().startsWith(assertionTable)) {
      fail("registration_guard_race_verification_missing");
    }
    if ((result.match(/^assert_case[ \t]*$/gm) || []).length !== 1) fail("registration_guard_race_verification_result_count_invalid");
    let tail = result.trimStart().slice(assertionTable.length);
    for (const session of ["a", "b", "verify"]) {
      tail = tail.trimStart();
      const warning = `${session}: WARNING:  there is no transaction in progress\n`;
      if (session !== "verify" && tail.startsWith(warning)) tail = tail.slice(warning.length);
      const actorTable = singleColumnResult("actor");
      if (!tail.startsWith(actorTable)) fail("registration_guard_race_session_teardown_result_invalid");
      tail = tail.slice(actorTable.length);
    }
    cleanupResults.push(tail);
  }
  // Validate every execution section before checking lifecycle output. Old
  // native captures without checkpoints must still fail this complete gate.
  for (const [index, result] of cleanupResults.entries()) {
    const marker = `registration_guard_race_cleanup_committed:${index + 1}`;
    if (result.trim() !== singleColumnResult("race_cleanup_checkpoint", marker).trim()) {
      fail("registration_guard_race_cleanup_checkpoint_invalid");
    }
  }
  return { status: "passed", sqlExecuted: true, permutations: RACE_CASES.length, observedLockWaits: RACE_CASES.length,
    sessions: sessionCount, committedCleanups: RACE_CASES.length,
    specSha256: SPEC_SHA256, stdoutSha256: hash(stdout), stderrSha256: hash(stderr) };
}

export function executeBinary(command, args, { environment, input = "", timeoutMs = 240_000 } = {}) {
  return new Promise((resolvePromise, reject) => {
    const child = spawn(command, args, { env: environment, stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "", bytes = 0;
    const timer = setTimeout(() => { child.kill("SIGKILL"); reject(new Error("registration_guard_race_process_timeout")); }, timeoutMs);
    const collect = target => chunk => {
      bytes += chunk.length;
      if (bytes > 2_000_000) { child.kill("SIGKILL"); reject(new Error("registration_guard_race_output_limit")); return; }
      if (target === "stdout") stdout += chunk; else stderr += chunk;
    };
    child.stdout.on("data", collect("stdout")); child.stderr.on("data", collect("stderr"));
    child.on("error", () => { clearTimeout(timer); reject(new Error("registration_guard_race_binary_unavailable")); });
    child.on("close", code => { clearTimeout(timer); resolvePromise({ code, stdout, stderr }); });
    child.stdin.on("error", () => {});
    child.stdin.end(input);
  });
}

export async function runRaceProbe({ argv = [], environment = process.env, cwd = process.cwd(),
  readConfig = readFile, execute = executeBinary } = {}) {
  if (argv.some(argument => argument !== "--plan")) fail("registration_guard_race_option_invalid");
  if (argv.includes("--plan") || (!environment.TASK_LOCAL_DB_URL && !environment.TASK_LOCAL_DB_NONCE)) return buildRacePlan();
  if (!environment.TASK_LOCAL_DB_URL || !environment.TASK_LOCAL_DB_NONCE) fail("registration_guard_race_context_incomplete");
  const config = await readConfig(resolve(cwd, "supabase/config.toml"), "utf8");
  validateIsolatedContext({ environment, cwd, config });
  const childEnvironment = Object.fromEntries(["PATH", "LANG", "LC_ALL"].filter(key => typeof environment[key] === "string").map(key => [key, environment[key]]));
  const version = await execute("isolationtester", ["-V"], { environment: childEnvironment, timeoutMs: 10_000 });
  if (version.code !== 0 || !/^isolationtester \(PostgreSQL\) 17(?:\.\d+)?\s*$/.test(version.stdout.trim())) {
    fail("registration_guard_race_pg17_isolationtester_required");
  }
  const output = await execute("isolationtester", [environment.TASK_LOCAL_DB_URL], {
    environment: { ...childEnvironment, PGOPTIONS: "-c test.registration_guard.approved_local_db=on", PG_TEST_TIMEOUT_DEFAULT: "15" },
    input: embeddedSpec(), timeoutMs: 240_000,
  });
  return validateIsolationOutput(output);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
  try {
    const argv = process.argv.slice(2);
    if (!argv.includes("--plan") && (process.env.TASK_LOCAL_DB_URL || process.env.TASK_LOCAL_DB_NONCE)) {
      const directory = await realpath(process.cwd());
      const metadata = await stat(directory);
      if (!metadata.isDirectory() || (typeof process.getuid === "function" && metadata.uid !== process.getuid())) fail("registration_guard_race_owned_cwd_required");
    }
    process.stdout.write(`${JSON.stringify(await runRaceProbe({ argv }))}\n`);
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : "registration_guard_race_failed"}\n`);
    process.exitCode = 1;
  }
}
